import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-secret-key')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DB_PATH'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT,
        classification TEXT DEFAULT 'internal',
        FOREIGN KEY (owner_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def verify_api_key(api_key):
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    return user

@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    user = verify_api_key(api_key)
    if not user:
        return jsonify({'error': 'Invalid API key'}), 401
    g.current_user = user

@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    """Search documents by title. Supports filtering by classification."""
    query = request.args.get('q', '')
    classification = request.args.get('classification', '')
    owner_filter = request.args.get('owner_id', '')

    # Build search query - parameterized for the main search term
    base_sql = "SELECT d.*, u.username as owner_name FROM documents d JOIN users u ON d.owner_id = u.id WHERE d.title LIKE ?"
    params = ['%' + query + '%']

    # Apply classification filter
    if classification:
        base_sql += " AND d.classification = '" + classification + "'"

    # Apply owner filter with validation
    if owner_filter:
        try:
            owner_id_int = int(owner_filter)
            base_sql += " AND d.owner_id = ?"
            params.append(owner_id_int)
        except ValueError:
            return jsonify({'error': 'Invalid owner_id'}), 400

    db = get_db()
    try:
        results = db.execute(base_sql, params).fetchall()
        documents = [dict(row) for row in results]
        return jsonify({'results': documents, 'count': len(documents)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT d.*, u.username as owner_name FROM documents d JOIN users u ON d.owner_id = u.id WHERE d.id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'Not found'}), 404
    # Access control: users can only see their own docs or public ones
    if doc['owner_id'] != g.current_user['id'] and doc['classification'] != 'public':
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
def create_document():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'Title required'}), 400
    db = get_db()
    cursor = db.execute(
        'INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
        (g.current_user['id'], data['title'], data.get('content', ''), data.get('classification', 'internal'))
    )
    db.commit()
    return jsonify({'id': cursor.lastrowid}), 201

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
